package server

const pageTemplate = `{{define "page"}}<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>{{if .Chapter}}{{.Root.Title}} · {{end}}{{.Saga.Manifest.Title}} · Review Saga</title>
<style>
:root{--ink:#18231d;--muted:#68746d;--paper:#f4f2eb;--card:#fffefa;--line:#d8d2c3;--accent:#14614d;--accent-soft:#e4efe9;--red:#a83c2d;--amber:#a66a09;--green:#267447;--code:#202620;--shadow:0 14px 38px #18231d14}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--paper);color:var(--ink);font:15px/1.55 system-ui,sans-serif}button,input,textarea{font:inherit}button{cursor:pointer}.topbar{position:sticky;top:0;z-index:30;height:58px;display:flex;align-items:center;gap:20px;padding:0 22px;background:#18231df5;color:white;border-bottom:1px solid #ffffff1a}.brand{font:700 12px monospace;letter-spacing:.13em;text-transform:uppercase}.view-tabs{display:flex;align-self:stretch}.view-tab{border:0;border-bottom:3px solid transparent;border-radius:0;padding:0 18px;background:transparent;color:#bdc8c1;font-weight:650}.view-tab.active{color:white;border-color:#8ed3b0}.top-meta{margin-left:auto;color:#aebbb4;font:12px monospace}.shell{display:grid;grid-template-columns:270px minmax(0,1fr);min-height:calc(100vh - 58px)}.sidebar{position:sticky;top:58px;height:calc(100vh - 58px);overflow:auto;padding:24px 20px;background:#ebe7db;border-right:1px solid var(--line)}.sidebar-title{display:block;color:var(--ink);text-decoration:none;font:600 24px/1.2 Georgia,serif;margin:6px 0 12px}.side-label,.eyebrow{margin:24px 0 8px;font:700 10px monospace;letter-spacing:.12em;text-transform:uppercase;color:var(--muted)}nav a,.file-tree a{display:flex;gap:8px;align-items:center;padding:6px 8px;margin:2px -8px;text-decoration:none;color:var(--ink);border-radius:7px}.file-tree a:hover,nav a:hover{background:#ded9cc}.nav-child{padding-left:13px}.file-tree .reviewed{color:var(--green)}.file-tree .selected{background:#d9e5dd;font-weight:700}.file-tree code{font-size:11px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.file-tree .counts{margin-left:auto;white-space:nowrap;font:10px monospace}.file-tree details{margin-left:10px}.file-tree summary{cursor:pointer;color:var(--muted);font:600 12px system-ui;padding:5px 0}.content{width:min(1420px,100%);padding:36px clamp(18px,4vw,54px) 110px}.view{display:none}.view.active{display:block}.page-heading{margin-bottom:28px}.page-heading h2{font:500 clamp(32px,5vw,46px)/1.12 Georgia,serif;margin:4px 0}.page-heading .eyebrow{margin:0}.breadcrumbs{margin:0 0 18px;font-size:13px}.breadcrumbs a{color:var(--accent)}.alert{background:#fff7e8;border:1px solid #dfcda7;border-radius:11px;padding:14px;margin:0 0 24px}.alert strong{display:block}.chapter-index{margin-top:34px;border-top:1px solid var(--line);padding-top:20px}.chapter-index>h2{font:500 25px Georgia,serif;margin:0 0 12px}.chapter-card{background:var(--card);border:1px solid var(--line);border-radius:11px;margin:9px 0}.chapter-card summary{display:flex;align-items:center;gap:12px;padding:13px 15px;cursor:pointer;list-style:none}.chapter-card summary::-webkit-details-marker{display:none}.chapter-card summary:after{content:'⌄';margin-left:auto;color:var(--muted)}.chapter-card[open] summary:after{transform:rotate(180deg)}.chapter-title{font:600 16px Georgia,serif}.chapter-status{margin-left:auto;color:var(--muted);font:700 10px monospace;text-transform:uppercase}.chapter-card summary:after{margin-left:0}.chapter-details{display:flex;align-items:center;gap:12px;padding:0 15px 14px;color:var(--muted);font-size:13px}.chapter-details .btn{margin-left:auto;text-decoration:none}.chapter-card.active{border-color:#76a793}.section{scroll-margin-top:75px;margin:26px 0}.section .section{margin-left:20px}.section-head{display:flex;justify-content:space-between;align-items:center;gap:16px;border-bottom:1px solid var(--line);padding-bottom:9px}.section h2{font:500 36px Georgia,serif;margin:0}.section .section h2{font-size:27px}.section-actions,.fragment-actions{display:flex;align-items:center;gap:6px}.review-status{font:11px monospace;text-transform:uppercase;color:var(--accent);margin-top:7px}.fragment{position:relative;scroll-margin-top:75px;background:var(--card);border:1px solid var(--line);border-radius:15px;margin:18px 0;padding:22px;box-shadow:var(--shadow);outline:0}.fragment.active-fragment{border-color:#76a793;box-shadow:0 0 0 2px #76a79342,var(--shadow)}.fragment-head{display:flex;justify-content:space-between;gap:12px;align-items:center}.fragment h3{margin:0;font:600 20px Georgia,serif}.btn,button{font:650 12px system-ui;border:0;border-radius:7px;padding:7px 10px;background:var(--accent);color:white}.btn-subtle{background:var(--accent-soft);color:var(--accent)}.icon-button{min-width:34px;font-size:18px;line-height:1;padding:7px;background:var(--accent-soft);color:var(--accent)}.diff-button{display:inline-flex;align-items:center;gap:6px}.diff-button svg{width:14px;height:14px}.fragment-stage{position:relative;margin-top:14px;min-height:70px}.fragment-frame{display:block;width:100%;min-height:430px;border:0;border-radius:9px;background:white}.fragment-image{display:block;max-width:100%;height:auto;margin:auto}.fragment-markdown{font:17px/1.7 Georgia,serif}.fragment-markdown pre,.plain{overflow:auto;background:#eeebe2;padding:12px;border-radius:8px;font:13px/1.5 monospace}.review-overlay{position:absolute;inset:0;width:100%;height:100%;pointer-events:none;overflow:visible}.review-overlay.drawing{pointer-events:auto;cursor:crosshair;background:#14614d0a}.annotation{fill:#ffcc0038;stroke:#d04832;stroke-width:5;vector-effect:non-scaling-stroke}.annotation.path{fill:none}.pending{stroke:#14614d;fill:#14614d20}.threads{margin-top:14px}.thread{border-left:3px solid #d59b28;padding:8px 12px;margin:9px 0;background:#fffaf0}.thread.suggestion{border-color:#5981bd}.thread.resolved{opacity:.65;border-color:#87948c}.thread-meta{font:11px monospace;color:var(--muted)}.suggestion-code{display:block;margin:8px 0;padding:10px;background:#e6f3ea;color:#174a2b;border-radius:6px;white-space:pre-wrap}.message{margin:8px 0;padding-top:7px;border-top:1px solid var(--line)}.message-fragment iframe{min-height:240px}.reply{display:grid;grid-template-columns:1fr auto;gap:6px;margin-top:8px}.reply input:not([type=hidden]),.thread-state input,.dialog-form input,.dialog-form textarea,.diff-compose input,.diff-compose textarea{width:100%;padding:8px;border:1px solid #bbb6aa;border-radius:7px}.thread-state{margin-top:6px}.text-anchor{background:#ffe797;padding:2px 5px;font-size:12px}.annotation-toolbox{position:fixed;z-index:50;left:calc(50% + 135px);transform:translateX(-50%);bottom:18px;display:flex;align-items:center;gap:5px;padding:8px;background:#18231df2;color:white;border:1px solid #ffffff22;border-radius:12px;box-shadow:0 14px 45px #18231d3d}.annotation-toolbox button{background:#ffffff14;color:white;white-space:nowrap}.annotation-toolbox button[aria-pressed=true]{background:#8ed3b0;color:#10261c}.tool-target{max-width:155px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;margin:0 6px;color:#cad4ce;font-size:11px}.dialog{width:min(520px,calc(100vw - 32px));border:1px solid var(--line);border-radius:14px;padding:0;background:var(--card);color:var(--ink);box-shadow:0 24px 80px #18231d55}.dialog::backdrop{background:#18231d70}.dialog-head{display:flex;align-items:center;gap:12px;padding:15px 18px;border-bottom:1px solid var(--line)}.dialog-head h2{font:600 19px Georgia,serif;margin:0}.dialog-head button{margin-left:auto;background:#e8e6df;color:var(--ink)}.dialog-form{padding:17px}.dialog-form textarea{min-height:78px;margin:9px 0}.decision-actions{display:flex;gap:7px;flex-wrap:wrap}.decision-actions .danger{background:#8b4238}.annotation-compose{position:fixed;z-index:90;right:24px;bottom:82px;width:min(500px,calc(100vw - 48px));display:none}.annotation-compose.open{display:block}.diff-drawer{position:fixed;z-index:80;inset:58px 0 0 auto;width:min(780px,94vw);background:#f8f7f2;box-shadow:-18px 0 55px #18231d30;transform:translateX(105%);transition:transform .22s ease;display:flex;flex-direction:column}.diff-drawer.open{transform:none}.drawer-backdrop{position:fixed;z-index:70;inset:58px 0 0;background:#18231d55;display:none}.drawer-backdrop.open{display:block}.drawer-head{display:flex;align-items:center;gap:12px;padding:16px 20px;border-bottom:1px solid var(--line);background:white}.drawer-head h2{font:600 18px Georgia,serif;margin:0}.drawer-head button{margin-left:auto;background:#e8e6df;color:var(--ink)}.drawer-body{overflow:auto;padding:18px 20px 100px}.code-workspace{display:grid;grid-template-columns:minmax(0,1fr) 290px;gap:22px;align-items:start}.code-heading{display:flex;align-items:end;justify-content:space-between;border-bottom:1px solid var(--line);padding-bottom:14px;margin-bottom:18px}.code-heading h2{font:500 32px Georgia,serif;margin:0}.related-saga{position:sticky;top:76px;background:var(--card);border:1px solid var(--line);border-radius:11px;padding:15px}.related-saga h2{font:600 19px Georgia,serif;margin:0 0 12px}.related-chapter{border-top:1px solid var(--line);padding-top:10px;margin-top:10px}.related-chapter>a{font-weight:700;color:var(--ink);text-decoration:none}.related-fragment{display:block;margin-top:8px;padding:8px;border-radius:7px;background:#f1eee5;color:var(--ink);text-decoration:none}.related-fragment strong{display:block}.related-fragment span{display:block;color:var(--muted);font-size:12px;margin-top:3px}.metric{padding:5px 10px;border:1px solid var(--line);border-radius:99px;color:var(--muted)}.remaining{background:#fff7e8;border:1px solid #dfcda7;border-radius:11px;padding:14px;margin:16px 0}.file-diff{scroll-margin-top:76px;margin:0 0 24px;border:1px solid #c8c4b9;border-radius:11px;overflow:hidden;background:white}.file-head{position:sticky;top:58px;z-index:5;display:flex;align-items:center;gap:12px;padding:11px 14px;background:#eceae3;border-bottom:1px solid #c8c4b9}.file-head code{font-weight:700;overflow-wrap:anywhere}.file-head .counts{margin-left:auto;font:12px monospace}.reviewed-badge{color:var(--green);font:700 11px monospace;text-transform:uppercase}.file-review{display:flex;gap:6px}.diff-lines{background:var(--code);color:#dce5dd}.diff-row{display:grid;grid-template-columns:54px 22px minmax(0,1fr) auto;align-items:start;min-height:29px;border-top:1px solid #ffffff0a;font:12px/1.55 ui-monospace,SFMono-Regular,Menlo,monospace}.diff-row:first-child{border-top:0}.diff-row.new{background:#173a28}.diff-row.old{background:#442522}.diff-row.event{background:#2b332d;color:#b9c5bd}.line-no{padding:5px 8px;text-align:right;color:#8e9b92;user-select:none}.sign{padding:5px 0;color:#aab7ae}.code-line{padding:5px 9px;white-space:pre-wrap;overflow-wrap:anywhere}.line-actions{display:flex;gap:3px;padding:3px 5px;opacity:0}.diff-row:hover .line-actions,.diff-row:focus-within .line-actions{opacity:1}.line-actions button{padding:3px 6px;background:#ffffff18;color:white;font:11px system-ui}.diff-thread-wrap{grid-column:3/5;padding:0 10px 8px}.diff-compose{position:fixed;z-index:100;right:24px;bottom:20px;width:min(520px,calc(100vw - 48px));padding:15px;background:white;border:1px solid var(--line);border-radius:12px;box-shadow:0 18px 65px #18231d4a;display:none}.diff-compose.open{display:block}.diff-compose-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:9px}.diff-compose-head strong{font:600 15px Georgia,serif}.diff-compose-head button{background:#e8e6df;color:var(--ink)}.diff-compose-fields{display:grid;grid-template-columns:1fr;gap:7px}.replacement{display:none}.diff-compose.suggesting .replacement{display:block}@media(max-width:980px){.code-workspace{grid-template-columns:1fr}.related-saga{position:static}}@media(max-width:780px){.topbar{padding:0 10px;gap:7px}.brand{display:none}.view-tab{padding:0 10px}.shell{display:block}.sidebar{position:static;height:auto;padding:16px 18px}.sidebar nav{display:none}.content{padding:22px 12px 118px}.section .section{margin-left:8px}.section h2{font-size:28px}.fragment{padding:16px}.fragment-head{align-items:flex-start}.chapter-details{align-items:flex-start;flex-wrap:wrap}.annotation-toolbox{left:10px;right:10px;transform:none;overflow-x:auto;justify-content:flex-start}.tool-target{display:none}.reply,.diff-compose-fields{grid-template-columns:1fr}.file-head{top:58px}.line-actions{opacity:1}.diff-row{grid-template-columns:42px 18px minmax(0,1fr)}.line-actions{grid-column:3}.diff-thread-wrap{grid-column:3}}
</style><script src="/app.js" defer></script></head><body>
<header class="topbar"><div class="brand">Review Saga</div><div class="view-tabs" aria-label="Review workspace"><button class="view-tab active" data-view-tab="saga">Saga</button><button class="view-tab" data-view-tab="code">Code Diff</button></div><div class="top-meta" hidden>{{len .Files}} files · {{.ReviewedFiles}} reviewed</div></header>
<div class="shell"><aside class="sidebar"><a class="sidebar-title" href="/">{{.Saga.Manifest.Title}}</a><div class="saga-side"><div class="side-label">Chapters</div>{{template "chapter-index" .Chapters}}{{if .Chapter}}<div class="side-label">On this page</div><nav>{{template "nav" .Root}}</nav>{{end}}</div><div class="code-side" hidden><div class="side-label">Changed files</div><div class="file-tree" role="tree">{{if .Code}}{{template "file-tree-nodes" .Code.Tree.Nodes}}{{end}}</div></div></aside>
<main class="content"><div class="view active" data-view="saga">{{if .Error}}<div class="alert" role="alert"><strong>Review readiness check failed</strong>{{.Error}}</div>{{else if .Diagnostic}}<div class="alert" role="alert"><strong>Review readiness check failed</strong>{{.Diagnostic}}</div>{{end}}{{if .Overview}}<header class="page-heading"><div class="eyebrow">Overview</div><h2>{{.Saga.Manifest.Title}}</h2></header>{{template "overview" .Root}}<section class="chapter-index"><h2>Continue with a chapter</h2>{{template "chapter-index" .Chapters}}</section>{{else}}<nav class="breadcrumbs" aria-label="Breadcrumb"><a href="/">Overview</a> <span aria-hidden="true">/</span> <span>{{.Root.Title}}</span></nav>{{template "section" .Root}}{{end}}</div>
<div class="view" data-view="code"><div class="code-workspace"><div class="code-main"><div class="code-heading"><div><div class="side-label">Complete comparison</div><h2>Code Diff</h2></div><span class="metric">{{.ReviewedFiles}} / {{len .Files}} files reviewed</span></div>{{with .Code.SelectedFile}}{{template "file-diff" .}}{{else}}<div class="remaining">No product code changes in this comparison.</div>{{end}}</div>{{if .Code.SelectedFile}}<aside class="related-saga" aria-label="Related saga context"><h2>Related saga context</h2>{{range .Code.RelatedSaga}}<section class="related-chapter"><a href="{{.Href}}">{{.Title}}</a>{{range .Fragments}}<a class="related-fragment" href="{{.Href}}"><strong>{{.Title}}</strong>{{if .Excerpt}}<span>{{.Excerpt}}</span>{{end}}</a>{{end}}</section>{{else}}<p>{{.Code.RelatedEmpty}}</p>{{end}}</aside>{{end}}</div></div></main></div>
<div class="annotation-toolbox" role="toolbar" aria-label="Annotation tools"><span class="tool-target" data-tool-target>No fragment selected</span><button type="button" data-tool="select" aria-pressed="true">Select</button><button type="button" data-tool="target" aria-pressed="false">Comment</button><button type="button" data-tool="text" aria-pressed="false">Highlight</button><button type="button" data-tool="rect" aria-pressed="false">Rectangle</button><button type="button" data-tool="draw" aria-pressed="false">Freehand</button></div>
<dialog class="dialog decision-dialog" aria-labelledby="decision-title"><div class="dialog-head"><h2 id="decision-title">Record a decision</h2><button type="button" data-close-decision aria-label="Close decision dialog">Close</button></div><form class="dialog-form" method="post" action="/api/review"><input type="hidden" name="target"><textarea name="body" placeholder="Optional review note"></textarea><div class="decision-actions"><button name="state" value="approved">Approve</button><button class="danger" name="state" value="rejected">Request changes</button><button class="btn-subtle" name="state" value="closed">Close review</button></div></form></dialog>
<form class="dialog annotation-compose" method="post" action="/api/thread" enctype="multipart/form-data"><input type="hidden" name="target"><input type="hidden" name="anchor"><input type="hidden" name="kind" value="comment"><div class="dialog-head"><h2>Comment on this fragment</h2><button type="button" data-close-annotation>Cancel</button></div><div class="dialog-form"><textarea name="body" placeholder="Start a review thread"></textarea><input type="file" name="attachment" accept="image/*,.svg,.html,.txt" multiple><button type="submit">Create thread</button></div></form>
<div class="drawer-backdrop" data-close-drawer></div><aside class="diff-drawer" aria-hidden="true" aria-label="Linked diffs"><div class="drawer-head"><div><div class="side-label">Attached code</div><h2>Linked diffs</h2></div><button type="button" data-close-drawer>Close</button></div><div class="drawer-body"></div></aside>
<form class="diff-compose" method="post" action="/api/thread" enctype="multipart/form-data"><input type="hidden" name="target"><input type="hidden" name="anchor"><input type="hidden" name="kind" value="comment"><div class="diff-compose-head"><strong>Comment on this change</strong><button type="button" data-close-diff-compose>Cancel</button></div><div class="diff-compose-fields"><textarea name="body" placeholder="What should the author know?"></textarea><textarea class="replacement" name="replacement" placeholder="Replacement code"></textarea><input type="file" name="attachment" accept="image/*,.svg,.html,.txt" multiple><button type="submit">Add to review</button></div></form>
</body></html>{{end}}

{{define "chapter-index"}}{{range .}}<details class="chapter-card {{if .Active}}active{{end}}"><summary><span class="chapter-title">{{.Title}}</span><span class="chapter-status">{{.Status}}</span></summary><div class="chapter-details"><span>{{.Summary}}</span><a class="btn" href="{{.URL}}">{{.Action}}</a></div></details>{{else}}<p>No chapters in this saga.</p>{{end}}{{end}}

{{define "file-tree-nodes"}}{{range .}}{{if eq .Kind "folder"}}<details {{if .Expanded}}open{{end}}><summary>{{.Name}} <span class="counts">{{.ReviewedCount}}/{{.FileCount}}</span></summary><div role="group">{{template "file-tree-nodes" .Children}}</div></details>{{else}}<a role="treeitem" class="{{if .File.Reviewed}}reviewed{{end}} {{if .File.Selected}}selected{{end}}" href="{{.File.Href}}" aria-current="{{if .File.Selected}}page{{else}}false{{end}}"><span>{{if .File.Reviewed}}✓{{else}}◇{{end}}</span><code>{{.Name}}</code><span class="counts">+{{.File.Added}} −{{.File.Deleted}}</span></a>{{end}}{{end}}{{end}}

{{define "nav"}}<a href="#{{.DOMID}}">{{.Title}}</a>{{range .FragmentViews}}<a class="nav-child" href="#{{.DOMID}}">{{if .Title}}{{.Title}}{{else}}{{.ID}}{{end}}</a>{{end}}{{if .ChildViews}}<div class="nav-child">{{range .ChildViews}}{{template "nav" .}}{{end}}</div>{{end}}{{end}}

{{define "diff-icon"}}<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><path d="M8 3v12a4 4 0 0 0 4 4h4M5 6l3-3 3 3M13 16l3 3-3 3"/></svg>{{end}}

{{define "decision-button"}}<button class="icon-button" type="button" data-review-target="{{.Target}}" data-review-title="{{if .Title}}{{.Title}}{{else}}{{.ID}}{{end}}" aria-label="Review decisions for {{if .Title}}{{.Title}}{{else}}{{.ID}}{{end}}">⋯</button>{{end}}

{{define "overview"}}<section id="{{.DOMID}}">{{if .ReviewState}}<div class="review-status">{{.ReviewState}} · {{attribution .ReviewAttribution}}</div>{{end}}<div class="section-actions">{{if .Changes}}<button class="btn-subtle diff-button" type="button" data-open-diffs="diffs-{{.DOMID}}">{{template "diff-icon"}} {{len .Changes}}</button>{{end}}{{template "decision-button" .}}</div>{{template "threads" .Threads}}{{range .FragmentViews}}{{template "fragment" .}}{{end}}{{if .Changes}}{{template "diff-template" .}}{{end}}</section>{{end}}

{{define "section"}}<section class="section {{.Kind}}" id="{{.DOMID}}"><div class="section-head"><h2>{{.Title}}</h2><div class="section-actions">{{if .Changes}}<button class="btn-subtle diff-button" type="button" data-open-diffs="diffs-{{.DOMID}}">{{template "diff-icon"}} {{len .Changes}}</button>{{end}}{{template "decision-button" .}}</div></div>{{if .ReviewState}}<div class="review-status">{{.ReviewState}} · {{attribution .ReviewAttribution}}</div>{{end}}{{template "threads" .Threads}}{{range .FragmentViews}}{{template "fragment" .}}{{end}}{{if .Changes}}{{template "diff-template" .}}{{end}}{{range .ChildViews}}{{template "section" .}}{{end}}</section>{{end}}

{{define "diff-template"}}<template id="diffs-{{.DOMID}}"><div class="file-diff"><div class="file-head"><strong>{{.Title}}</strong><span class="counts">{{len .Changes}} changes</span></div><div class="diff-lines">{{range .Changes}}{{template "diff-row" .}}{{end}}</div></div></template>{{end}}

{{define "fragment"}}<article class="fragment" id="{{.DOMID}}" data-target="{{.Target}}" data-fragment-title="{{if .Title}}{{.Title}}{{else}}{{.ID}}{{end}}" tabindex="0"><div class="fragment-head"><div><h3>{{if .Title}}{{.Title}}{{else}}{{.ID}}{{end}}</h3>{{if .ReviewState}}<div class="review-status">{{.ReviewState}} · {{attribution .ReviewAttribution}}</div>{{end}}</div><div class="fragment-actions">{{if .Changes}}<button type="button" class="btn-subtle diff-button" data-open-diffs="diffs-{{.DOMID}}">{{template "diff-icon"}} {{len .Changes}}</button>{{end}}{{template "decision-button" .}}</div></div>
<div class="fragment-stage">{{if .Markdown}}<div class="fragment-markdown" data-selectable>{{.Markdown}}</div>{{else if .Plain}}<pre class="plain" data-selectable>{{.Plain}}</pre>{{else if .Interactive}}<iframe class="fragment-frame" sandbox="allow-scripts" src="{{.URL}}" title="{{.Title}}"></iframe>{{else if .Image}}<img class="fragment-image" src="{{.URL}}" alt="{{.Title}}">{{else}}<a href="{{.URL}}">Open fragment</a>{{end}}<svg class="review-overlay" viewBox="0 0 1000 1000" preserveAspectRatio="none">{{range .Threads}}{{range .Anchor.Shapes}}{{if eq .Type "rect"}}<rect class="annotation" x="{{coord .X}}" y="{{coord .Y}}" width="{{coord .Width}}" height="{{coord .Height}}"/>{{else if eq .Type "ellipse"}}<ellipse class="annotation" cx="{{coord .X}}" cy="{{coord .Y}}" rx="{{coord .Width}}" ry="{{coord .Height}}"/>{{else if eq .Type "line"}}<line class="annotation path" x1="{{coord .X}}" y1="{{coord .Y}}" x2="{{coord .Width}}" y2="{{coord .Height}}"/>{{else if eq .Type "path"}}<polyline class="annotation path" points="{{points .Points}}"/>{{end}}{{end}}{{end}}</svg></div>
{{template "threads" .Threads}}{{if .Changes}}{{template "diff-template" .}}{{end}}</article>{{end}}

{{define "file-diff"}}<article class="file-diff" id="{{.ID}}"><header class="file-head"><code>{{.Path}}</code>{{if .Reviewed}}<span class="reviewed-badge">✓ Reviewed · {{attribution .ReviewAttribution}}</span>{{end}}<span class="counts">+{{.Added}} −{{.Deleted}}</span><form class="file-review" method="post" action="/api/diff-review"><input type="hidden" name="uri" value="{{.URI}}"><input type="hidden" name="file" value="{{.ID}}"><button name="state" value="{{if .Reviewed}}unreviewed{{else}}reviewed{{end}}">{{if .Reviewed}}Unmark{{else}}Mark reviewed{{end}}</button></form></header><div class="diff-lines">{{range .Atoms}}{{template "diff-row" .}}{{end}}</div></article>{{end}}

{{define "diff-row"}}{{if eq .Kind "event"}}<div class="diff-row event"><span class="line-no">•</span><span class="sign">↳</span><span class="code-line">{{.Event}} {{if .OldPath}}{{.OldPath}} → {{.NewPath}}{{else}}{{.Path}}{{end}}</span><span class="line-actions"><button type="button" data-diff-action="comment" data-diff-ref="{{.URI}}" data-target="{{.Target}}">Comment</button></span>{{template "diff-threads" .Threads}}</div>{{else}}<div class="diff-row {{.Side}}"><span class="line-no">{{.Line}}</span><span class="sign">{{if eq .Side "new"}}+{{else}}−{{end}}</span><span class="code-line">{{.Content}}</span><span class="line-actions"><button type="button" data-diff-action="comment" data-diff-ref="{{.URI}}" data-target="{{.Target}}">Comment</button><button type="button" data-diff-action="suggestion" data-diff-ref="{{.URI}}" data-target="{{.Target}}" data-content="{{.Content}}">Suggest</button></span>{{template "diff-threads" .Threads}}</div>{{end}}{{end}}

{{define "diff-threads"}}{{if .}}<div class="diff-thread-wrap">{{template "threads" .}}</div>{{end}}{{end}}

{{define "threads"}}{{if .}}<div class="threads">{{range .}}{{$thread := .}}<article class="thread {{.State}} {{.Kind}}"><div class="thread-meta">{{attribution .Attribution}} · {{if .Kind}}{{.Kind}}{{else}}{{.Anchor.Type}}{{end}} · {{.State}}: {{attribution .StateAttribution}}</div>{{if .Anchor.Text}}<div class="text-anchor" data-text-target="{{.Target}}" data-exact="{{.Anchor.Text.Exact}}">“{{.Anchor.Text.Exact}}”</div>{{end}}{{if .Suggestion}}<code class="suggestion-code">{{.Suggestion.Replacement}}</code>{{end}}{{range $index,$message := .Messages}}<div class="message"><div class="thread-meta">{{attribution $message.Attribution}}</div>{{range index $thread.MessageViews $index}}<div class="message-fragment">{{if .Markdown}}<div class="fragment-markdown">{{.Markdown}}</div>{{else if .Interactive}}<iframe class="fragment-frame" sandbox="allow-scripts" src="{{.URL}}"></iframe>{{else if .Image}}<img class="fragment-image" src="{{.URL}}" alt="attachment">{{else}}<pre class="plain">{{.Plain}}</pre>{{end}}</div>{{end}}</div>{{end}}<form class="reply" method="post" action="/api/reply" enctype="multipart/form-data"><input type="hidden" name="thread" value="{{.ID}}"><input type="hidden" name="target" value="{{.Target}}"><input name="body" placeholder="Reply"><button>Reply</button><input type="file" name="attachment" accept="image/*,.svg,.html,.txt" multiple></form><form class="thread-state" method="post" action="/api/thread-state"><input type="hidden" name="thread" value="{{.ID}}"><input type="hidden" name="target" value="{{.Target}}"><button name="state" value="{{if eq .State "resolved"}}open{{else}}resolved{{end}}">{{if eq .State "resolved"}}Reopen{{else}}Resolve{{end}}</button></form></article>{{end}}</div>{{end}}{{end}}`
